# 3.2 Inside plant and animal cells · 7Bs.02, 7Bs.04, 7TWSm.01
# =====================================================================================================
READ["3.2"] = L(
    H("Why is spinach in the fridge crisp?",
      "Fresh spinach is crisp and stands up. After two days on the table it is soft and floppy.",
      "Something inside each cell has changed. Make a guess, then find the answer in this lesson."),
    I("Parts of an animal cell",
      "An animal cell (for example a cell from inside your cheek) has four main parts.",
      fig=ANIMAL,
      table=[["Part", "Job (function)"],
             ["**nucleus**", "controls the cell; contains DNA, the instructions for the cell"],
             ["**cytoplasm**", "a jelly where most chemical reactions take place"],
             ["**cell membrane**", "a thin layer that controls what goes into and out of the cell"],
             ["**mitochondria**", "release energy from food by aerobic respiration"]]),
    I("Parts of a plant cell",
      "A plant cell (for example a leaf cell) has all four parts of an animal cell, **plus** three more.",
      fig=PLANT,
      table=[["Extra part", "Job"],
             ["**cell wall**", "made of cellulose; strong and stiff; supports the cell and gives it a fixed shape"],
             ["**chloroplasts**", "contain green chlorophyll, which absorbs light energy for photosynthesis (making food)"],
             ["**large sap vacuole**", "filled with cell sap; keeps the cell firm"]]),
    I("Real life: crisp or floppy?",
      "In fresh spinach each sap vacuole is full of water and pushes outwards against the cell wall, like air in a tyre. The cells are firm, so the leaf is crisp.",
      then=["When the leaf loses water, the vacuoles shrink, the cells are no longer pushed firm, and the leaf flops.",
            "Put a floppy leaf in cold water for half an hour: the vacuoles fill again and the leaf becomes crisp."]),
    I("Staining cells",
      "Many cells are almost colourless, so they are hard to see. A **stain** colours some parts.",
      table=[["Cells", "Stain", "What you see"], ["cheek cells", "methylene blue", "pale blue cells with a dark blue nucleus"], ["onion cells", "iodine solution", "yellow-brown cells with a darker nucleus"]],
      then=["Only ever use cheek cells from your own mouth, collected with a clean cotton bud, and put used buds in disinfectant."]),
    Y("Which part?",
      mcq("s7u03r21", "Which part controls what enters and leaves a cell?",
          [("cell membrane", True, "Yes – it lets some substances through and keeps others out."), ("cell wall", False, "The cell wall supports the cell; water passes through it freely."),
           ("nucleus", False, "The nucleus controls the cell's activities, but not what passes in and out."), ("cytoplasm", False, "Reactions happen in the cytoplasm.")],
          "Think of a gate around the cell.", "The cell membrane controls what enters and leaves.")),
    I("Not every plant cell is green",
      "Cells from an **onion bulb** have a cell wall and a sap vacuole, but **no chloroplasts**.",
      then=["The bulb grows underground in the dark, so its cells cannot photosynthesise and do not need chloroplasts. Root cells have none either.",
            "**Every** plant cell has a cell wall, but **not every** plant cell has chloroplasts."]),
    I("Plant and animal cells compared",
      "A side-by-side comparison:",
      table=[["Part", "Plant cell", "Animal cell"],
             ["nucleus, cytoplasm, cell membrane, mitochondria", "✓", "✓"], ["cell wall", "✓", "✗"], ["chloroplasts", "✓ (in green parts)", "✗"],
             ["large sap vacuole", "✓ – takes up most of the cell", "✗ (only small vacuoles, if any)"], ["shape", "regular, box-like", "irregular"]],
      then=["Plants have cell walls because they have no skeleton: the stiff walls and firm vacuoles hold a tall tree or a sunflower upright."]),
    Y("Plant, animal or both?",
      grid("s7u03r22", "Where is each part found?", ["Plant cells only", "Both"],
           [("chloroplast", "Plant cells only"), ("nucleus", "Both"), ("cell wall", "Plant cells only"), ("mitochondria", "Both"), ("large sap vacuole", "Plant cells only"), ("cell membrane", "Both")],
           "Three parts are extra in plant cells.", "Cell wall, chloroplasts and the large sap vacuole are only in plant cells; the other four parts are in both.")),
    I("Thinking about models",
      "A model plant cell can be built from a shoebox (cell wall), plastic food wrap (membrane), a balloon of water (sap vacuole), a plum (nucleus) and green beads (chloroplasts).",
      table=[["Strengths", "Limitations"],
             ["shows the parts and where they are", "far too big"], ["is three-dimensional, like a real cell", "food wrap cannot control what passes in and out"],
             ["easy to handle and explain", "no cytoplasm or mitochondria; parts do not work"]],
      then=["Every model has **strengths** and **limitations**. Evaluating a model means describing both."]),
    X("The cell wall is not the membrane",
      "Some students think the cell wall controls what goes into a plant cell.",
      "Plant cells have **both**. The cell wall is outside and gives support; water passes through it freely. Inside it, the cell **membrane** controls what goes in and out."),
    K("Key points",
      "Animal and plant cells both have a **nucleus, cytoplasm, cell membrane and mitochondria**.",
      "Plant cells also have a **cell wall**, **chloroplasts** (in green parts) and a **large sap vacuole**.",
      "A full sap vacuole keeps a plant cell firm; stains help us see colourless cells.",
      "Models have strengths and limitations."),
    book=BK(
        [("nucleus", "controls the cell and contains DNA"), ("cytoplasm", "jelly where most chemical reactions happen"), ("cell membrane", "controls what enters and leaves the cell"),
         ("mitochondria", "release energy from food by aerobic respiration"), ("cell wall", "stiff cellulose layer that supports a plant cell"),
         ("chloroplast", "contains chlorophyll; absorbs light for photosynthesis"), ("sap vacuole", "space full of cell sap that keeps a plant cell firm")],
        [], [],
        [Ex("Give the function of:", ("the nucleus", "controls the cell; contains DNA"), ("chloroplasts", "absorb light energy for photosynthesis"), ("mitochondria", "release energy by aerobic respiration")),
         Ex("Name three parts found in plant cells but not in animal cells.", ans="cell wall, chloroplasts, large sap vacuole"),
         Ex("A cell has a cell wall and a large vacuole but no chloroplasts. Is it from a plant or an animal? Where might it come from?", ans="A plant – for example a root or an onion bulb, which grows in the dark."),
         Ex("Explain why a watered plant stands up but a dry plant wilts. Use the words vacuole and cell wall.",
            ans="When watered, sap vacuoles fill and push against the cell walls, so cells are firm and support the plant; without water the vacuoles shrink and the cells go soft.", think=True),
         Ex("A student models an animal cell with a plastic bag of jelly and a cherry. Give one strength and one limitation.",
            ans="Strength: shows the membrane, cytoplasm and nucleus in the right places. Limitation: much too big, no mitochondria, the bag cannot control what goes in and out.", think=True)],
        ["name the parts of plant and animal cells and their functions", "compare plant and animal cells", "explain why some plant cells have no chloroplasts", "evaluate a model of a cell"],
        look=["the comparison table", "strengths and limitations of the model cell"],
        note="Read it after the video: parts of cells and their jobs, staining, the comparison and models (answers at the back)."),
)

